# Diagnostic integration guard. Historical guard is intentionally retained beside this file.
. (Join-Path $PSScriptRoot 'diagnostic-profile-root-v6.ps1')
. (Join-Path (Split-Path -Parent $PSScriptRoot) 'integration-fresh-circle-v1.ps1')
$CircleHistoricalIntegration=(Get-Command Assert-FactoryIntegrationSources).ScriptBlock
$CircleHistoricalLease=(Get-Command Assert-LeaseIssuedMetadata).ScriptBlock
function Assert-FactoryIntegrationSources([string]$Root,[object]$SourceInputs){if($SourceInputs.kind -ceq 'factory-circle-source-inputs-diagnostic-v6'){return Assert-CircleDiagnosticSourceInputs $Root $SourceInputs};& $CircleHistoricalIntegration $Root $SourceInputs}
function Assert-CircleFinalPlanAdmission([object]$Plan){if($Plan.kind -ne 'factory-circle-incremental-compile-plan-v1' -or [string]::IsNullOrWhiteSpace([string]$Plan.candidate) -or $Plan.phase -ne 'final' -or $Plan.executionEligible -ne $true -or $Plan.qualification -ne 'diagnostic-native-only-not-qualified'){throw 'Circle diagnostic final plan rejected'};return $true}
function Assert-LeaseIssuedMetadata([string]$Path,[string]$Hash,[string]$RunRoot,[int]$Count,[string]$CompileHash,[string]$ExeHash,[string]$SerializerHash,[string]$ProducerRoot,[object]$SourceInputs){if($SourceInputs.kind -ne 'factory-circle-source-inputs-diagnostic-v6'){& $CircleHistoricalLease $Path $Hash $RunRoot $Count $CompileHash $ExeHash $SerializerHash $ProducerRoot $SourceInputs;return};if((Get-DiagnosticHash $Path) -cne $Hash){throw 'Circle diagnostic issued metadata hash drift'};$m=Get-DiagnosticJson $Path;if($m.kind -ne 'factory-prelaunch-capture-metadata-v2' -or $m.version -ne 2 -or $m.expectedCount -ne $Count -or $m.runRoot -cne ([IO.Path]::GetFullPath($RunRoot)) -or $m.case.id -ne $SourceInputs.caseID -or $m.case.hash -ne $SourceInputs.caseHash -or $m.sourceHash -ne $SourceInputs.sourceHash -or $m.frozenTupleBound -ne $false){throw 'Circle diagnostic issued metadata envelope mismatch'};foreach($r in @($m.plan,$m.compile,$m.exe,$m.renderer,$m.candidateTuple,$m.sourceBoundCandidateTuple,$m.recipe,$m.candidateContext)){if($null -eq $r){throw 'Circle diagnostic issued metadata ref missing'}};foreach($join in @(@{n='plan';m=$m.plan;s=$SourceInputs.planRef},@{n='compile';m=$m.compile;s=$SourceInputs.compileRef},@{n='exe';m=$m.exe;s=$SourceInputs.exeRef},@{n='renderer';m=$m.renderer;s=$SourceInputs.rendererRef},@{n='tuple';m=$m.candidateTuple;s=$SourceInputs.tupleRef},@{n='binding';m=$m.sourceBoundCandidateTuple;s=$SourceInputs.bindingRef},@{n='recipe';m=$m.recipe;s=$SourceInputs.recipeRef},@{n='context';m=$m.candidateContext;s=$SourceInputs.contextRef})){if($join.m.path -cne $join.s.path -or $join.m.sha256 -cne $join.s.sha256 -or [int64]$join.m.bytes -ne [int64]$join.s.bytes){throw ('Circle diagnostic issued '+$join.n+' reference mismatch')}};$rows=@($m.captures);if($rows.Count -ne $Count){throw 'Circle diagnostic issued capture count mismatch'};for($i=0;$i -lt $rows.Count;$i++){if($rows[$i].run -ne ($i+1) -or [string]$rows[$i].captureID -notmatch '^capture/[0-9a-f]{32}$' -or [string]$rows[$i].imageID -notmatch '^image/[0-9a-f]{32}$' -or $rows[$i].provenance.sourceHash -cne $SourceInputs.sourceHash){throw 'Circle diagnostic issued identity mismatch'}};return $m}
